import { Component } from '@angular/core';
import { timeout } from 'rxjs';

@Component({
    selector: 'app-transaction-start',
    host: { class: 'childRouteFlex' },
    templateUrl: './transaction-start.component.html',
    styleUrls: ['./transaction-start.component.css']
})
export class TransactionStartComponent {
    showButtonChoseIsIncome = false;
    firstLoad = true;

    buttonCreate: any;

    constructor() {
        // this.buttonCreate = document.getElementById('buttonCreate');
		// this.buttonCreate.addEventListener('mouseover', (event) => {
		// 	// Get the position of the mouse relative to the button
		// 	const x = event.clientX - button.getBoundingClientRect().left;
		// 	const y = event.clientY - button.getBoundingClientRect().top;

		// 	// Calculate the percentage of mouse position
		// 	const xPercent = (x / button.clientWidth) * 100;
		// 	const yPercent = (y / button.clientHeight) * 100;

		// 	console.log(xPercent, yPercent);

		// 	// adjust the degree of the gradient to match the mouse position
		// 	// so that where the mouse is, the gradient is at 0 degrees
		// 	// and where the mouse is not, the gradient is at 180 degrees
		// 	const degree = (xPercent / 100) * 180 - 90;


		// 	button.style	.setProperty('--gradient-degree', degree + "deg");
		//   });
    }

    CreateTransaction() {
        this.showButtonChoseIsIncome = !this.showButtonChoseIsIncome;
        this.firstLoad = false;
    }
}
<div class="mainChild">
    <div class="list-container">
        <app-transaction-list></app-transaction-list>
    </div>
</div>

<div
	id="button-create"
    class="default-button bottom-button invert-button"
    ngClass="{{ showButtonChoseIsIncome ? 'active' : '' }}"
>
    <div
        class="button-create"
        ngClass="{{ showButtonChoseIsIncome ? 'active' : !firstLoad ? 'off' : '' }}"
        (click)="CreateTransaction()"
    >
        <div class="button-create-text secondary">
            <span *ngIf="!showButtonChoseIsIncome">Create Transaction</span>
            <span *ngIf="showButtonChoseIsIncome">X</span>
        </div>
    </div>
    <div class="income-expense-container">
        <div class="sub-button">
			<span>Income</span>
		</div>
        <div class="sub-button">
			<span>Expense</span>
		</div>
    </div>
    <!-- <span class="secondary">Create Transaction</span> -->
</div>
